// Methods whose first two arguments are world-space (x, y) coordinates.
const XY_METHODS = new Set([
  'fillRect', 'clearRect', 'rect', 'ellipse', 'arc',
  'moveTo', 'lineTo', 'fillText', 'strokeText'
]);

