input.new_string:
scale(sx, sy) {
  // Canvas post-multiplication: scale the x column (a,b) by sx and the
  // y column (c,d) by sy; the accumulated translation (e,f) stays fixed.
  matrix[0] *= sx; matrix[1] *= sx;
  matrix[2] *= sy; matrix[3] *= sy;
  record('scale', [sx, sy]);
},

