test('cityWorldPoint inverts the live transform at the pub, Lotte bridge and map edges', () => {
  const world = loadWorld();
  mediaQuery.matches = false;
  const points = [
    [City.PLACES.pub.x, City.PLACES.pub.y],
    [City.PLACES.lotte.x, City.PLACES.lotte.y],
    [516, 624], // musician's narrow bridge
    [78, 48], [1722, 48], [78, 1072], [1722, 1072],
    [City.LAND.x, City.LAND.y],
    [City.LAND.x + City.LAND.w, City.LAND.y + City.LAND.h]
  ];
  const cameras = [
    { camera: 'street', zoom: 1 },
    { camera: 'overview', zoom: 1 },
    { camera: 'overview', zoom: 2 }
  ];
  for (const cfg of cameras) {
    const { scene } = render(world, cityView(cfg.camera, false, { zoom: cfg.zoom }), 1);
    const tr = scene.cityTransform;
    assert.ok(tr && Number.isFinite(tr.scale) && tr.scale > 0, 'street transform scale is missing');
    assert.ok(Number.isFinite(tr.tx) && Number.isFinite(tr.ty), 'street transform translation is missing');
    for (const [wx, wy] of points) {
      const sx = wx * tr.scale + tr.tx;
      const sy = wy * tr.scale + tr.ty;
      const back = scene.cityWorldPoint(sx, sy);
      assert.ok(
        Math.hypot(back.x - wx, back.y - wy) < 1e-7,
        `${cfg.camera} zoom${cfg.zoom} click inversion failed at world ${wx},${wy}`
      );
    }
  }
});

